WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT browser, DATE_TRUNC('MONTH', started_at) AS activity_month, country, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, MAX(started_at) AS ended_at, SORT_ARRAY(COLLECT_SET(country)) AS country_list, APPROX_PERCENTILE(island_id, 0.95) AS island_id_p95, MIN(started_at) AS first_started_at FROM sessions_sessions GROUP BY browser, activity_month, country HAVING island_id_p95 > 0
